
const DEFAULT_FONTS = {
    "Helvetica.ttf": "",
    "Helvetica-Bold.ttf": "",
    "Helvetica-Oblique.ttf": "",
    "Helvetica-BoldOblique.ttf": "",
    "Times.ttf": "",
    "Times-Bold.ttf": "",
    "Times-Oblique.ttf": "",
    "Times-BoldOblique.ttf": "",
    "Courier.ttf": "",
    "Courier-Bold.ttf": "",
    "Courier-Oblique.ttf": "",
    "Courier-BoldOblique.ttf": "",
    "NotoSansJP-Regular.otf": "",
    "RobotoMedium.ttf": ""
};

export function getFonts() {
    const fonts: Record<string, string> = {};
    for (const [name, base64] of Object.entries(DEFAULT_FONTS)) {
        if (base64 && base64.length > 0) {
            fonts[name] = base64;
        }
    }
    return fonts;
}